UPDATE catalog_products SET verified_claims = (SELECT coalesce(json_group_array(value), '[]') FROM json_each(catalog_products.verified_claims) WHERE value NOT LIKE 'Preço unitário publicado:%') WHERE store_id IS NOT NULL AND json_valid(verified_claims);
